import{z as l,x as o,o as r,c as p,q as s,j as i,D as E,d as t,s as n,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"深流水与时钟频率","description":"","frontmatter":{"title":"深流水与时钟频率","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/deep-pipeline-clock.md","filePath":"cs/deep-pipeline-clock.md","lastUpdated":1791063341000}'),d={name:"cs/deep-pipeline-clock.md"};function c(m,a,F,P,h,C){const A=o("Mermaid");return r(),p("div",null,[a[2]||(a[2]=s('<h1 id="深流水与时钟频率" tabindex="-1">深流水与时钟频率 <a class="header-anchor" href="#深流水与时钟频率" aria-label="Permalink to &quot;深流水与时钟频率&quot;">​</a></h1><div class="epigraph"><p>切更多级可以抬高频率，但误预测要填的级数也变多；最优深度随预测准确率、工作负载和功耗一起动，不是越深越快。</p><footer>—— 据 Hartstein and Puzak, The Optimum Pipeline Depth for a Microprocessor, ISCA 2002；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/retire-precise-exception">上一课</a> 把架构写钉在 ROB 头，并指出级深会放大冲刷量。<a href="/cs/pipeline-five-stage">五级</a> 已经用切段换频率。本课不重讲精确异常。缺口是<strong>乱序核把流水切到 15–30 级时，时钟与误预测损失如何一起进入 CPI 公式</strong>——Pentium 4 式超深流水的教训。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理想情况下，级深加倍则时钟近加倍，同一 IPC 下吞吐加倍。但 <a href="/cs/gshare-predictor">gshare</a> 的损失拍 ≈ 从 IF 到核对的级数；窗口更大、恢复更重，<a href="/cs/speculation-recovery">推测恢复</a> 更贵。功耗随触发器数量与旁路上升。缺口不是再加一个退休口，而是<strong>把频率收益与每条指令的额外停顿、能耗放在同一张账上</strong>。</p><p><span class="marginnote">数字实例：5 级流水一次误预测约浪费 4 拍；切成 20 级后同样的事故要填约 19 拍。若分支占指令 20%、预测准确率 95%，每条指令平均多付 0.2 × 0.05 × 19 ≈ 0.19 拍——这笔「误预测税」随级数线性涨，频率收益必须跑赢它才划算。</span></p><p><span class="marginnote">Hartstein–Puzak 用解析与模拟指出：存在最优流水深度；预测变差或能耗权重大时，最优点变浅。Pentium 4 的长管线后来被更短、更宽的核取代，是这条曲线的工业注脚。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把单指令延迟写成「级数 × 周期」。吞吐仍是每拍 uop 数。优化目标可以是性能、性能/瓦或 SPEC 分数。设计旋钮：切哪一段（ALU 旁路、数据 cache 命中、前端译码）、是否加转发跨越更多级、是否用半周期设计。</p><p><span class="marginnote">直觉类比：切级像把装配线拆成更多工位——传送带能转得更快（频率高），可一旦发现装错了（误预测），传送带越长、报废的在制品越多。「最优深度」就是提速赚的恰好被报废赔的追平的那一点。</span></p>',10)),(r(),i(B,null,{default:E(()=>[n(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEEP%5B%22%E5%8A%A0%E6%B7%B1%E7%BA%A7%E6%95%B0%22%5D%20--%3E%20FREQ%5B%22%E5%91%A8%E6%9C%9F%E7%BC%A9%E7%9F%AD%22%5D%0A%20%20DEEP%20--%3E%20PEN%5B%22%E8%AF%AF%E9%A2%84%E6%B5%8B%E5%A1%AB%E7%AE%A1%E6%9B%B4%E8%B4%B5%22%5D%0A%20%20DEEP%20--%3E%20FF%5B%22%E8%A7%A6%E5%8F%91%E5%99%A8%E4%B8%8E%E6%97%81%E8%B7%AF%E5%A2%9E%E5%8A%A0%22%5D%0A%20%20FREQ%20--%3E%20PERF%5B%22%E5%8F%AF%E8%83%BD%E6%8F%90%E9%AB%98%E5%90%9E%E5%90%90%22%5D%0A%20%20PEN%20--%3E%20PERF%0A%20%20FF%20--%3E%20PWR%5B%22%E5%8A%9F%E8%80%97%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[e("a",{href:"/cs/cpi-amdahl"},"CPI 与阿姆达尔"),t("：停顿项里控制冒险随级深近似线性涨，数据转发失败的气泡也涨。若工作负载分支密、预测不准，加深会让有效 CPI 涨得比频率更快，净时间变差。乱序窗口可以掩盖部分数据延迟，但掩盖不了「整条错误路径上的前端填充」。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为「频率翻倍 = 快一倍」。账要记在有效 CPI 上：频率抬高的同时误预测税与转发气泡也在涨，CPI 变差可能吃掉全部收益——Pentium 4 的超深管线最终被更短、更宽的核取代，就是这条曲线的工业注脚。")],-1)),(r(),i(B,null,{default:E(()=>[n(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20FE%5B%22%E5%8F%96%E6%8C%87%EF%BC%9A%E8%B5%B0%E9%94%99%E5%88%86%E6%94%AF%E6%96%B9%E5%90%91%22%5D%20--%3E%20DEC%5B%22%E8%AF%91%E7%A0%81%EF%BC%9A%E9%94%99%E8%AF%AF%E6%8C%87%E4%BB%A4%E7%BB%A7%E7%BB%AD%E6%B6%8C%E5%85%A5%22%5D%0A%20%20DEC%20--%3E%20EX%5B%22%E6%89%A7%E8%A1%8C%EF%BC%9A%E9%94%99%E8%AF%AF%E6%8E%A8%E6%B5%8B%E8%B6%8A%E8%B5%B0%E8%B6%8A%E6%B7%B1%22%5D%0A%20%20EX%20--%3E%20CHK%5B%22%E6%A0%B8%E5%AF%B9%E7%82%B9%EF%BC%9A%E5%8F%91%E7%8E%B0%E9%A2%84%E6%B5%8B%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20CHK%20--%3E%20FL%5B%22%E5%86%B2%E5%88%B7%E5%85%A8%E9%83%A8%E5%9C%A8%E9%80%94%E6%8C%87%E4%BB%A4%22%5D%0A%20%20FL%20--%3E%20RE%5B%22%E9%87%8D%E5%8F%96%E6%AD%A3%E7%A1%AE%E8%B7%AF%E5%BE%84%EF%BC%8C%E9%87%8D%E6%96%B0%E5%A1%AB%E5%85%85%2015-30%20%E7%BA%A7%22%5D%0A%20%20RE%20--%3E%20GO%5B%22%E6%B5%81%E6%B0%B4%E7%BA%BF%E5%86%8D%E6%AC%A1%E6%BB%A1%E8%BD%BD%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p>这门课序在前端与乱序核收束：预测、重命名、IQ、LSQ、前端缓存、退休、级深，共同决定单核 ILP。下一单元转向 cache 替换与一致性协议的进阶细节。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不选某个商业核的级数当标准答案。也不把多发射、多核当成「加深」的替代公式——那是并行课。功耗模型只到「触发器与投机浪费」，不去工艺库。</p><p>后课默认：更深不是自动更快；准确预测是深管线的许可证。单元切换：替换策略从 LRU 讲起，不再加宽前端。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>级深抬频率，同时抬误预测与功耗；存在最优深度。</li><li>乱序掩盖数据延迟，掩盖不了错误路径的填充。</li><li>下一课序从 cache 替换（LRU/PLRU）接上。</li><li>出处：Hartstein and Puzak, <em>ISCA</em>, 2002；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',6))])}const f=l(d,[["render",c]]);export{u as __pageData,f as default};
